2	import { encodedSize } from "./input.js";
3	import { RUBBING_TYPE_NAMES } from "./rubbings.js";
4	
5	/**
6	 * The journal messages (protocol v10, §3, §11, §13 and §16). The intel module's leads reach one player each: a rumor
7	 * (an island or a sector), a carrier sighting, a no-lead notice, and a rumor going stale or resolved. At a dock a player
8	 * buys a targeted rumor (25 gold); the server answers every request once. None of these names a player, a rubbing or
9	 * the position of a source, a cache or a ship: they carry types, island and sector indexes and names, and ticks. The
10	 * player's journal itself (the room's log of these, their known islands and what they could buy) is in their own
11	 * private status, so a reconnecting player reads it back.
12	 */
13	export const JournalMessageType = {
14	  /** Server → client: one lead or journal notice (`JournalMessage`), to its player only. */
15	  Lead: "journal",
16	  /** Client → server: buy a targeted rumor about a missing type (`BuyRumorMessage`). */
17	  BuyRumor: "buy-rumor",
18	  /** Server → client: the answer to one purchase request, to its sender only (`RumorResultMessage`). */
19	  RumorResult: "rumor-result",
20	} as const;
21	
22	/** Why a lead was given (the intel module's `IntelLeadReason`). */
23	export const LEAD_REASON_NAMES = ["start", "fresh", "targeted", "replacement"] as const;
24	export type LeadReasonName = (typeof LEAD_REASON_NAMES)[number];
25	
26	const tickSchema = z.int().min(0);
27	const typeSchema = z.enum(RUBBING_TYPE_NAMES);
28	const nameSchema = z.string().min(1).max(64);
29	const reasonSchema = z.enum(LEAD_REASON_NAMES);
30	
31	/** A lead from the server, as the intel module words it. */
32	export const journalMessageSchema = z.discriminatedUnion("kind", [
33	  /** A journal rumor: a missing type at an island (a sealed source) or in a sector (a recovery cache). */
34	  z.strictObject({
35	    kind: z.literal("rumor"),
36	    tick: tickSchema,
37	    entry: z.int().min(1),
