1	import { WORLD_STEPS_PER_SECOND } from "@pirate-sea-race/content";
2	import {
3	  JournalMessageType,
4	  parseJournal,
5	  parseJournalMessage,
6	  parseKnownIslands,
7	  parseRumorOffers,
8	  parseRumorResultMessage,
9	  type BuyRumorMessage,
10	  type JournalEntry,
11	  type JournalMessage,
12	  type KnownIsland,
13	  type RumorOfferName,
14	  type RumorRefusalName,
15	  type RumorResultMessage,
16	} from "@pirate-sea-race/protocol";
17	import { kitDescriptions } from "@pirate-sea-race/simulation/fruits";
18	import { createIntelConfig, sectorOf, type IntelConfig } from "@pirate-sea-race/simulation/intel";
19	import { typeName } from "./hud.js";
20	
21	/**
22	 * §3, §11 and §13's journal in the browser: M opens and closes it (Escape closes it too), and it lists this player's
23	 * leads (the type, the island or sector, why they got it, stale ones greyed with what replaced them), the islands they
24	 * know, their collected types and their kit with its description. Moored at a dock, it sells a targeted rumor about each
25	 * missing type. A toast announces each new lead, and the sea shows its sector borders while the journal is open or a
26	 * sector lead is active. Everything down to `JournalPanel` is plain data, for unit tests; `JournalPanel` and
27	 * `applyJournal` touch the page. The helm stays live while the journal is open.
28	 */
29	
30	/** A targeted rumor's price (§11), as the server charges it (`objectiveRules.rumorPrice`). */
31	export const RUMOR_PRICE = 25;
32	
33	/** This player's journal fields, from its private status and its ship. */
34	export interface JournalStatus {
35	  readonly journal: readonly JournalEntry[];
36	  readonly knownIslands: readonly KnownIsland[];
37	  readonly offers: readonly { readonly type: string; readonly offer: RumorOfferName }[];
38	  readonly rubbings: readonly string[];
39	  readonly gold: number;
40	  readonly kit: string;
41	  /** The ship is moored at a dock and in the world (not in a duel, not waiting to respawn). */
42	  readonly moored: boolean;
43	}
44	
45	export interface Line {
46	  readonly text: string;
47	  readonly state: string;
48	}
49	
50	/** The journal's fields of this player's private status, as decoded. */
51	export interface JournalStatusFields {
52	  readonly journal: string;
53	  readonly knownIslands: string;
54	  readonly rumorOffers: string;
55	  readonly rubbings: string;
56	  readonly gold: number;
57	  readonly kit: string;
58	  readonly mode: string;
59	}
60	
61	/**
62	 * The journal's status from the decoded private status and the dock this player's ship is moored at (-1 at sea):
63	 * it is moored for buying only at a dock and in the world (not in a duel, not waiting to respawn).
64	 */
65	export function journalStatusOf(fields: JournalStatusFields | undefined, dock: number | undefined): JournalStatus | undefined {
66	  if (fields === undefined) return undefined;
67	  return {
68	    journal: parseJournal(fields.journal),
69	    knownIslands: parseKnownIslands(fields.knownIslands),
70	    offers: parseRumorOffers(fields.rumorOffers),
71	    rubbings: fields.rubbings === "" ? [] : fields.rubbings.split(","),
72	    gold: fields.gold,
73	    kit: fields.kit,
74	    moored: dock !== undefined && dock !== -1 && fields.mode === "sea",
75	  };
76	}
77	
78	/** One journal entry as the journal lists it. */
79	export interface RumorLine {
80	  readonly n: number;
81	  readonly type: string;
82	  /** "Sun: Old Stones (island)", "Moon: a cache in Central Waters", "Sun: a carrier seen in Central Waters 45 s before", "Moon: no lead". */
83	  readonly text: string;
84	  /** Why the player got it: "start", "fresh", "targeted", "replacement", or "sighting". */
85	  readonly reason: string;
86	  /** "active", "stale" or "resolved". */
87	  readonly status: string;
88	  /** " stale" or " resolved", or "" while active. */
89	  readonly statusText: string;
90	  /** For a stale entry: what replaced it ("Replaced by #3: …"), or that no lead followed yet. */
91	  readonly replaced: string;
92	}
93	
94	/** A Buy button: one per missing type. */
95	export interface BuyButton {
96	  readonly type: string;
97	  readonly label: string;
98	  /** "available", "covered", "no-lead", "not-at-dock", "gold" or "pending". */
99	  readonly state: string;
100	  readonly disabled: boolean;
101	}
102	
103	export interface JournalView {
104	  readonly hidden: boolean;
105	  /** Newest first, or one "No leads yet" line (state "empty"). */
106	  readonly rumors: readonly RumorLine[];
107	  /** Or one line saying none are known yet (state "empty"). */
108	  readonly islands: readonly Line[];
109	  readonly collected: string;
110	  readonly kit: { readonly name: string; readonly specials: readonly string[]; readonly advantage: string; readonly vulnerability: string };
111	  readonly buys: readonly BuyButton[];
112	  /** The last purchase's answer. */
113	  readonly message: Line;
114	}
115	
116	/** An entry's line: the type and where it points. */
117	export function entryText(entry: JournalEntry): string {
118	  const type = typeName(entry.type);
119	  switch (entry.kind) {
120	    case "island":
121	      return `${type}: ${entry.target} (island)`;
122	    case "sector":
123	      return `${type}: a recovery cache in ${entry.target}`;
124	    case "sighting":
125	      return `${type}: a carrier seen in ${entry.target} ${Math.round((entry.tick - entry.seenTick) / WORLD_STEPS_PER_SECOND)} s before`;
126	    case "no-lead":
127	      return `${type}: no lead`;
128	  }
129	}
130	
131	/** Every entry, newest first, with the reason, the status and a stale entry's replacement. */
132	export function rumorLines(entries: readonly JournalEntry[]): RumorLine[] {
133	  return [...entries].reverse().map((entry) => {
134	    const next = entries.find((each) => each.n === entry.replacedBy);
135	    const replaced = entry.status !== "stale" ? "" : next !== undefined ? `Replaced by #${next.n}: ${entryText(next)}` : "Stale: its target no longer holds it";
136	    return {
137	      n: entry.n,
138	      type: entry.type,
139	      text: `#${entry.n} ${entryText(entry)}`,
140	      reason: entry.kind === "sighting" ? "sighting" : entry.reason,
141	      status: entry.status,
142	      statusText: entry.status === "active" ? "" : ` ${entry.status}`,
143	      replaced,
144	    };
145	  });
146	}
147	
148	/** The known islands (§13): name, the ruin as last seen, and whether this player solved it. */
149	export function islandLines(known: readonly KnownIsland[], islandName: (island: number) => string): Line[] {
150	  return known.map((island) => {
151	    const state = island.solved ? "solved" : island.unlocked ? "unlocked" : "locked";
152	    const ruin = island.solved ? "ruin solved by you" : island.unlocked ? "ruin unlocked" : "ruin locked";
153	    return { text: `${islandName(island.island)}: ${ruin}`, state };
154	  });
155	}
156	
157	/**
158	 * The Buy buttons: one per missing type the server offers. A type whose lead is free coverage is `covered`, one with
159	 * nothing to sell `no-lead`; otherwise the ship must be moored at a dock and the player hold the price. While a request
160	 * waits for its answer every button is disabled.
161	 */
162	export function buyButtons(status: JournalStatus | undefined, pending: string | undefined): BuyButton[] {
163	  if (status === undefined) return [];
164	  return status.offers.map(({ type, offer }) => {
165	    const name = typeName(type);
166	    const button = (state: string, text: string, disabled = true): BuyButton => ({ type, label: `${name}: ${text}`, state, disabled });
167	    if (pending !== undefined) return button("pending", pending === type ? "asking…" : `Buy a rumor (${RUMOR_PRICE} gold)`);
168	    if (offer === "covered") return button("covered", "covered (a free lead is coming)");
169	    if (offer === "none") return button("no-lead", "no lead to sell now");
170	    if (!status.moored) return button("not-at-dock", "moor at a dock to buy a rumor");
171	    if (status.gold < RUMOR_PRICE) return button("gold", `not enough gold (${RUMOR_PRICE})`);
172	    return button("available", `Buy a rumor (${RUMOR_PRICE} gold)`, false);
173	  });
174	}
175	
176	const REFUSALS: Readonly<Record<RumorRefusalName, string>> = {
177	  busy: "Two requests are already waiting",
178	  "not-in-play": "Rumors are sold only during the match",
179	  "not-at-dock": "Moor at a dock to buy a rumor",
180	  "player-in-duel": "Not during a duel",
181	  "player-disconnected": "Not while disconnected",
182	  "insufficient-gold": "Not enough gold",
183	  covered: "Nothing to pay for: a free lead covers it",
184	  capped: "No fresher sighting to sell yet",
185	  none: "No lead to sell",
186	  duplicate: "That request was already answered",
187	};
188	
189	/** The answer to the last purchase, as the journal says it. */
190	export function resultLine(result: RumorResultMessage | undefined): Line {
191	  if (result === undefined) return { text: "", state: "none" };
192	  if (result.outcome === "bought") return { text: `Bought a rumor about ${typeName(result.type)} (−${result.price} gold)`, state: "bought" };
193	  return { text: `${typeName(result.type)}: ${REFUSALS[result.reason]}, nothing charged`, state: result.reason };
194	}
195	
196	/** The whole journal. */
197	export function journalView(open: boolean, status: JournalStatus | undefined, pending: string | undefined, last: RumorResultMessage | undefined, islandName: (island: number) => string): JournalView {
198	  const kit = kitDescriptions[(status?.kit ?? "duelist") as keyof typeof kitDescriptions] ?? kitDescriptions.duelist;
199	  const rumors = rumorLines(status?.journal ?? []);
200	  const islands = islandLines(status?.knownIslands ?? [], islandName);
201	  return {
202	    hidden: !open,
203	    rumors: rumors.length > 0 ? rumors : [{ n: 0, type: "", text: "No leads yet", reason: "", status: "empty", statusText: "", replaced: "" }],
204	    islands: islands.length > 0 ? islands : [{ text: "None yet: islands you sight are noted here", state: "empty" }],
205	    collected: (status?.rubbings.length ?? 0) === 0 ? "none yet" : status!.rubbings.map(typeName).join(", "),
206	    kit: { name: kit.name, specials: [`U: ${kit.specials[0]}`, `I: ${kit.specials[1]}`], advantage: kit.advantage, vulnerability: kit.vulnerability },
207	    buys: buyButtons(status, pending),
208	    message: resultLine(last),
209	  };
210	}
211	
212	/** A toast: a new lead, said briefly over the sea. */
213	export interface Toast {
214	  readonly title: string;
215	  readonly detail: string;
216	}
217	
218	/** The toast for a lead, or undefined for a notice that is not one (a rumor resolved quietly). */
219	export function toastOf(lead: JournalMessage): Toast | undefined {
220	  switch (lead.kind) {
221	    case "rumor": {
222	      const where = lead.target.kind === "island" ? lead.target.name : `a recovery cache in ${lead.target.name}`;
223	      return { title: `New lead (${lead.reason}): ${typeName(lead.type)}`, detail: `Try ${where}.` };
224	    }
225	    case "carrier-sighting":
226	      return {
227	        title: `Carrier sighting: ${lead.sightings.map((sighting) => typeName(sighting.type)).join(", ")}`,
228	        detail: `${lead.sightings.map((sighting) => `${typeName(sighting.type)} seen in ${sighting.name}`).join("; ")}, ${Math.round((lead.tick - lead.seenTick) / WORLD_STEPS_PER_SECOND)} s ago.`,
229	      };
230	    case "no-lead":
231	      return { title: `No lead: ${typeName(lead.type)}`, detail: "Every copy is out of reach for now." };
232	    case "rumor-stale":
233	      return { title: `Stale rumor: ${typeName(lead.type)}`, detail: "Its target no longer holds it." };
234	    case "rumor-resolved":
235	      return undefined;
236	  }
237	}
238	
239	/** Where focus goes on Tab inside the open journal: the next of `count` buttons (Shift: the previous), wrapping. */
240	export function nextFocus(count: number, current: number, backwards: boolean): number {
241	  if (count === 0) return -1;
242	  if (current < 0) return backwards ? count - 1 : 0;
243	  return (current + (backwards ? count - 1 : 1)) % count;
244	}
245	
246	/** The sea's sector grid (§3), as the intel rules cut it. */
247	const intelConfig: IntelConfig = createIntelConfig({ preset: "slice", finalIsland: { x: 0, y: 0 } });
248	
249	/** The first tile of each band after the first: where `sectorOfTile` changes from one band to the next. */
250	export function bandStarts(tiles: number, bands: number): number[] {
251	  return Array.from({ length: bands - 1 }, (_, index) => Math.ceil(((index + 1) * tiles) / bands));
252	}
253	
254	/** How long a sector's name shows after the ship enters it, in milliseconds. */
255	export const SECTOR_NAME_MS = 4000;
256	
257	export interface SectorOverlay {
258	  /** Only while the journal is open or a sector lead is active, so the sea stays clean. */
259	  readonly visible: boolean;
260	  /** The border lines' tiles, the columns' and rows' starts: none while hidden. */
261	  readonly columns: readonly number[];
262	  readonly rows: readonly number[];
263	  /** The ship's sector, or -1. */
264	  readonly sector: number;
265	  /** The sector's name for a moment after entering it (while visible), else "". */
266	  readonly label: string;
267	}
268	
269	/**
270	 * The sector borders over the sea: shown while the journal is open or the player holds an active sector lead, with
271	 * the name of the sector the ship is in for `SECTOR_NAME_MS` after it enters it. `entered` is the scene's memory of
272	 * the last sector and when it was entered; the new memory comes back with the overlay.
273	 */
274	export function sectorOverlay(input: {
275	  readonly journalOpen: boolean;
276	  readonly entries: readonly JournalEntry[];
277	  readonly own: { readonly x: number; readonly y: number } | undefined;
278	  readonly entered: { readonly sector: number; readonly at: number } | undefined;
279	  readonly now: number;
280	}): { readonly overlay: SectorOverlay; readonly entered: { readonly sector: number; readonly at: number } | undefined } {
281	  const visible = input.journalOpen || input.entries.some((entry) => entry.kind === "sector" && entry.status === "active");
282	  const sector = input.own === undefined ? -1 : sectorOf(intelConfig, input.own);
283	  const entered = sector < 0 ? input.entered : input.entered?.sector === sector ? input.entered : { sector, at: input.now };
284	  const showing = visible && sector >= 0 && entered !== undefined && input.now - entered.at < SECTOR_NAME_MS;
285	  return {
286	    overlay: {
287	      visible,
288	      columns: visible ? bandStarts(intelConfig.widthTiles, intelConfig.sectorColumns) : [],
289	      rows: visible ? bandStarts(intelConfig.heightTiles, intelConfig.sectorRows) : [],
290	      sector,
291	      label: showing ? intelConfig.sectorNames[sector]! : "",
292	    },
293	    entered,
294	  };
295	}
296	
297	/** A world tick count after which a request with no answer (dropped by the rate cap) no longer holds the buttons. */
298	const PENDING_TIMEOUT_TICKS = 5 * WORLD_STEPS_PER_SECOND;
299	
300	/**
301	 * The journal's behaviour, as `main.ts` wires it: M toggles it, Escape closes it, Tab and Shift+Tab move focus among
302	 * its buttons while it is open (`focus`), a Buy button sends `buy-rumor` with a fresh request id and disables the
303	 * buttons until the answer, and each new lead raises a toast (a lead seen before, resent by a replay, raises none).
304	 */
305	export class JournalPanel {
306	  private open = false;
307	  private status: JournalStatus | undefined;
308	  private pending: { readonly type: string; readonly requestId: string; readonly since: number } | undefined;
309	  private last: RumorResultMessage | undefined;
310	  private readonly seen = new Set<string>();
311	  private requests = 0;
312	  private worldTick = 0;
313	
314	  constructor(
315	    private readonly send: (type: string, message: unknown) => void,
316	    private readonly render: (view: JournalView) => void,
317	    private readonly toast: (toast: Toast) => void,
318	    private readonly focus: (backwards: boolean) => void,
319	    private readonly islandName: (island: number) => string,
320	  ) {}
321	
322	  get isOpen(): boolean {
323	    return this.open;
324	  }
325	
326	  /** The journal's entries, for the sea's sector overlay. */
327	  entries(): readonly JournalEntry[] {
328	    return this.status?.journal ?? [];
329	  }
330	
331	  keydown(event: Pick<KeyboardEvent, "code" | "repeat"> & { readonly shiftKey?: boolean }): boolean {
332	    if (event.code === "KeyM") {
333	      if (!event.repeat) this.toggle();
334	      return true;
335	    }
336	    if (!this.open) return false;
337	    if (event.code === "Escape") {
338	      this.toggle();
339	      return true;
340	    }
341	    if (event.code === "Tab") {
342	      this.focus(event.shiftKey === true);
343	      return true;
344	    }
345	    return false;
346	  }
347	
348	  toggle(): void {
349	    this.open = !this.open;
350	    this.draw();
351	    if (this.open) this.focus(false);
352	  }
353	
354	  update(status: JournalStatus | undefined, worldTick: number): void {
355	    this.status = status;
356	    this.worldTick = worldTick;
357	    if (this.pending !== undefined && worldTick - this.pending.since > PENDING_TIMEOUT_TICKS) this.pending = undefined;
358	    this.draw();
359	  }
360	
361	  /** A lead from the server: a toast the first time it is seen. */
362	  lead(message: unknown): void {
363	    const lead = parseJournalMessage(message);
364	    if (lead === undefined) return;
365	    const key = JSON.stringify(lead);
366	    if (this.seen.has(key)) return;
367	    this.seen.add(key);
368	    const toast = toastOf(lead);
369	    if (toast !== undefined) this.toast(toast);
370	  }
371	
372	  /** The answer to a purchase: the pending request (if this is its answer) is over. */
373	  result(message: unknown): void {
374	    const result = parseRumorResultMessage(message);
375	    if (result === undefined) return;
376	    if (this.pending?.requestId === result.requestId) this.pending = undefined;
377	    this.last = result;
378	    this.draw();
379	  }
380	
381	  /** A Buy button: only an available one sends. */
382	  buy(type: string): void {
383	    const button = buyButtons(this.status, this.pending?.type).find((each) => each.type === type);
384	    if (button === undefined || button.disabled) return;
385	    const requestId = `j${++this.requests}`;
386	    this.pending = { type, requestId, since: this.worldTick };
387	    this.send(JournalMessageType.BuyRumor, { requestId, type: type as BuyRumorMessage["type"] } satisfies BuyRumorMessage);
388	    this.draw();
389	  }
390	
391	  private draw(): void {
392	    this.render(journalView(this.open, this.status, this.pending?.type, this.last, this.islandName));
393	  }
394	}
395	
396	function field(root: ParentNode, id: string): HTMLElement {
397	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
398	  if (element === null) throw new Error(`missing journal field ${id}`);
399	  return element;
400	}
401	
402	function item(text: string, state: string): HTMLLIElement {
403	  const li = document.createElement("li");
404	  li.textContent = text;
405	  li.dataset["state"] = state;
406	  return li;
407	}
408	
409	/**
410	 * Whether the page's Buy buttons (their types, in page order) are already the view's: then the same elements stay,
411	 * and so does the focus on one of them. Otherwise (a type bought or collected, the first draw) they are replaced.
412	 */
413	export function sameButtons(current: readonly string[], wanted: readonly string[]): boolean {
414	  return current.length === wanted.length && current.every((type, index) => type === wanted[index]);
415	}
416	
417	/** Writes the journal into the page as readable text, and its Buy buttons. */
418	export function applyJournal(root: ParentNode, view: JournalView): void {
419	  field(root, "journal").hidden = view.hidden;
420	  field(root, "journal-rumors").replaceChildren(
421	    ...view.rumors.map((rumor) => {
422	      const li = item("", rumor.status);
423	      li.dataset["reason"] = rumor.reason;
424	      li.dataset["type"] = rumor.type;
425	      li.dataset["n"] = String(rumor.n);
426	      const text = document.createElement("span");
427	      text.textContent = rumor.text;
428	      const reason = document.createElement("em");
429	      reason.className = "reason";
430	      reason.textContent = rumor.reason;
431	      const status = document.createElement("span");
432	      status.className = "status";
433	      status.textContent = rumor.statusText;
434	      const replaced = document.createElement("small");
435	      replaced.textContent = rumor.replaced;
436	      li.append(text, " ", reason, status, replaced);
437	      return li;
438	    }),
439	  );
440	  field(root, "journal-islands").replaceChildren(...view.islands.map((line) => item(line.text, line.state)));
441	  field(root, "journal-collected").textContent = view.collected;
442	  field(root, "journal-kit").textContent = view.kit.name;
443	  field(root, "journal-kit-specials").textContent = view.kit.specials.join(" · ");
444	  field(root, "journal-kit-description").textContent = `Advantage: ${view.kit.advantage}. Vulnerability: ${view.kit.vulnerability}.`;
445	  const buys = field(root, "journal-buys");
446	  const existing = new Map([...buys.querySelectorAll<HTMLButtonElement>("button[data-type]")].map((button) => [button.dataset["type"]!, button]));
447	  const buttons = view.buys.map((buy) => {
448	    const button = existing.get(buy.type) ?? document.createElement("button");
449	    button.type = "button";
450	    button.dataset["type"] = buy.type;
451	    button.dataset["state"] = buy.state;
452	    button.textContent = buy.label;
453	    button.disabled = buy.disabled;
454	    return button;
455	  });
456	  // The same button elements stay, so focus stays where it is across redraws (20 a second).
457	  if (!sameButtons([...existing.keys()], view.buys.map((buy) => buy.type))) buys.replaceChildren(...buttons);
458	  const message = field(root, "journal-message");
459	  message.textContent = view.message.text;
460	  message.dataset["state"] = view.message.state;
461	}
462	
463	/** How long a toast stays up, in milliseconds. */
464	export const TOAST_MS = 4000;
465	
466	/** Shows a toast over the sea for `TOAST_MS`; a newer one replaces it. */
467	export function showToast(root: ParentNode, toast: Toast, timers: { hide?: number }): void {
